    return map[normalized] ?? map['English'] ?? key;
  }

  static String format(
    String key,
    String locale, {
    required Map<String, String> params,
  }) {
    var value = t(key, locale);
    params.forEach((placeholder, replacement) {
      value = value.replaceAll('{$placeholder}', replacement);
    });
    return value;
  }

  static String queueStatusLabel(ExchangeQueueStatus status, String locale) {
    switch (status) {
      case ExchangeQueueStatus.low:
        return t('queue_low', locale);
      case ExchangeQueueStatus.moderate:
        return t('queue_moderate', locale);
      case ExchangeQueueStatus.busy:
        return t('queue_busy', locale);
      case ExchangeQueueStatus.closed:
        return t('queue_closed', locale);
    }
  }

  static String crowdLevelLabel(CrowdReportLevel level, String locale) {
    switch (level) {
      case CrowdReportLevel.quiet:
        return t('crowd_quiet', locale);
      case CrowdReportLevel.moderate:
        return t('crowd_moderate', locale);
      case CrowdReportLevel.busy:
        return t('crowd_busy', locale);
      case CrowdReportLevel.veryBusy:
        return t('crowd_very_busy', locale);
    }
  }

  static String formatRecency(
    DateTime? updatedAt,
    String locale, {
    DateTime? now,
  }) {
    final clock = now ?? DateTime.now();
    if (updatedAt == null) return t('recency_none', locale);
    final diff = clock.difference(updatedAt);
    if (diff.inMinutes < 1) return t('recency_just_now', locale);
    if (diff.inMinutes < 60) {
      return format(
        'recency_min_ago',
        locale,
        params: {'minutes': '${diff.inMinutes}'},
      );
    }
    if (diff.inHours < 24) {
      return format(
        'recency_hr_ago',
        locale,
        params: {'hours': '${diff.inHours}'},
      );
    }
    if (diff.inDays == 1) return t('recency_day_ago', locale);
    return format(
      'recency_days_ago',
      locale,
      params: {'days': '${diff.inDays}'},
    );
  }

  static String formatBestTimeHint(BestTimeHint hint, String locale) {
    if (!hint.hasEnoughData) return t('best_time_insufficient', locale);
    final hour = hint.quietestHour;
    if (hour == null) return t('best_time_insufficient', locale);
    final countMatch =
        RegExp(r'based on (\d+) reports').firstMatch(hint.message);
    final count = countMatch?.group(1) ?? '0';
    return format(
      'best_time_quiet',
      locale,
      params: {
        'time': _formatHour(hour, locale),
        'count': count,
      },
    );
  }

  static String formatQueueBadgeLabel(
    ExchangeQueueStatus status,
    int? estimatedMinutes,
    String locale,
  ) {
    if (status == ExchangeQueueStatus.closed) {
      return queueStatusLabel(status, locale);
    }
    final wait = estimatedMinutes ?? 0;
    if (wait <= 0) return queueStatusLabel(status, locale);
    return format(
      'queue_badge_with_wait',
      locale,
      params: {
        'status': queueStatusLabel(status, locale),
        'minutes': '$wait',
      },
    );
  }

  static String _formatHour(int hour, String locale) {
    final period = hour >= 12 ? t('time_pm', locale) : t('time_am', locale);
    final h = hour % 12 == 0 ? 12 : hour % 12;
    return '$h:00 $period';
  }

